-- PIF alignment with the Launch Decision Pack (decision D-027): three
-- engagement types (Fellow, Intern, Volunteer), the nine Cohort 1 role
-- families, a cohort label and a test flag on applications.
-- Safe to import more than once (IF NOT EXISTS / INSERT IGNORE / guarded UPDATE).

ALTER TABLE career_opportunities
    ADD COLUMN IF NOT EXISTS engagement_type VARCHAR(12) NOT NULL DEFAULT 'fellow' AFTER code;

-- The application keeps the engagement type it was made for, even if the role is edited later.
ALTER TABLE job_applications
    ADD COLUMN IF NOT EXISTS engagement_type VARCHAR(12) NOT NULL DEFAULT 'fellow' AFTER opportunity_id,
    ADD COLUMN IF NOT EXISTS cohort VARCHAR(12) NULL AFTER engagement_type,
    ADD COLUMN IF NOT EXISTS is_test TINYINT(1) NOT NULL DEFAULT 0 AFTER cohort;

-- PTMS-HR-STD-002 role code for Frontend Developer is FE (it was FD).
UPDATE career_opportunities SET code = 'FE' WHERE code = 'FD' AND slug = 'frontend-developer-fellow';

